if (!raw) {
  throw new Error("OpenAI nu a returnat conținut.");
}

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error(
    `Răspunsul OpenAI nu este JSON valid: ${error.message}\nRăspuns primit: ${raw}`
  );
}

return [
  {
    json: parsed
  }
];

