const base64 = $json.base64 ?? "";
const mimetype = $json.mimetype ?? "image/jpeg";
const fileName = $json.fileName ?? "tv-label.jpg";

if (!base64) {
  throw new Error("Nu există base64 în input.");
}

return [
  {
    json: {
      ok: true,
      fileName,
      mimetype,
      image_data_url: `data:${mimetype};base64,${base64}`
    }
  }
];

const body = $json.body ?? {};
const data = body.data ?? {};
const key = data.key ?? {};
const msg = data.message ?? {};

const image = msg.imageMessage ?? null;
const video = msg.videoMessage ?? null;
const audio = msg.audioMessage ?? null;
const document = msg.documentMessage ?? null;
const sticker = msg.stickerMessage ?? null;

const remoteJid = key.remoteJid ?? '';

const telefon = remoteJid
  .replace('@s.whatsapp.net', '')
  .replace('@g.us', '');

const fromMe = key.fromMe === true;

const directie = fromMe
  ? 'outgoing'
  : 'incoming';

let tip = 'necunoscut';

if (image) {
  tip = 'image';
} else if (video) {
  tip = 'video';
} else if (audio) {
  tip = 'audio';
} else if (document) {
  tip = 'document';
} else if (sticker) {
  tip = 'sticker';
} else if (
  msg.conversation ||
  msg.extendedTextMessage?.text
) {
  tip = 'text';
}

const mesaj =
  msg.conversation ??
  msg.extendedTextMessage?.text ??
  image?.caption ??
  video?.caption ??
  document?.caption ??
  '';

const media =
  image ??
  video ??
  audio ??
  document ??
  sticker ??
  null;

return [
  {
    json: {
      event: body.event ?? '',
      telefon,
      nume: data.pushName ?? '',
      directie,
      tip,
      mesaj,

      media: media
        ? {
            mediaType: tip,
            url: media.url ?? '',
            mimetype: media.mimetype ?? '',
            fileLength: media.fileLength ?? '',
            mediaKey: media.mediaKey ?? '',
            directPath: media.directPath ?? '',
            fileName: media.fileName ?? '',
            seconds: media.seconds ?? null,
            width: media.width ?? null,
            height: media.height ?? null
          }
        : null,

      metadata: {
        messageId: key.id ?? '',
        remoteJid,
        fromMe,
        timestamp: data.messageTimestamp ?? null,
        source: data.source ?? ''
      },

      evolution: {
        instance: body.instance ?? '',
        server_url: body.server_url ?? '',
        apikey: body.apikey ?? '',
        messageId: key.id ?? ''
      }
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  throw new Error('Istoricul conversației este gol.');
}

const conversatii = items
  .map(item => item.json)
  .sort((a, b) => {
    const dataA = new Date(a.created_at).getTime();
    const dataB = new Date(b.created_at).getTime();

    if (dataA !== dataB) {
      return dataA - dataB;
    }

    return Number(a.id) - Number(b.id);
  });

const clientId = conversatii[0].client_id;

if (!clientId) {
  throw new Error(
    'client_id lipsește din istoricul conversației.'
  );
}

const parseVision = (mesaj) => {
  if (typeof mesaj !== 'string') {
    return null;
  }

  try {
    const rezultat = JSON.parse(mesaj);

    if (
      rezultat &&
      typeof rezultat === 'object' &&
      (
        rezultat.marca ||
        rezultat.model ||
        rezultat.serie ||
        rezultat.cod_produs ||
        rezultat.tip_tv ||
        rezultat.diagonala ||
        rezultat.cod_placa ||
        rezultat.alte_coduri
      )
    ) {
      return rezultat;
    }
  } catch {
    return null;
  }

  return null;
};

const istoric = conversatii.map(conversatie => {
  const vision = conversatie.tip === 'image'
    ? parseVision(conversatie.mesaj)
    : null;

  return {
    id: conversatie.id,
    message_id: conversatie.message_id ?? null,
    directie: conversatie.directie,
    tip: conversatie.tip,
    mesaj: vision
      ? '[Rezultat analiză imagine TV]'
      : conversatie.mesaj,
    vision,
    data: conversatie.created_at
  };
});

const rezultateVision = istoric
  .filter(conversatie => conversatie.vision)
  .map(conversatie => ({
    conversation_id: conversatie.id,
    message_id: conversatie.message_id,
    data: conversatie.data,
    ...conversatie.vision
  }));

const ultimulMesaj = istoric[istoric.length - 1];

if (!ultimulMesaj) {
  throw new Error(
    'Nu a putut fi identificat ultimul mesaj.'
  );
}

return [
  {
    json: {
      client_id: clientId,
      timezone: 'Europe/Bucharest',
      data_analizei: new Date().toISOString(),
      numar_mesaje_context: istoric.length,
      mesaj_nou: ultimulMesaj,
      rezultate_vision: rezultateVision,
      istoric_conversatie: istoric
    }
  }
];

