parameters.jsCode:
const response = $json;

const content = response?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error(
    'OpenAI nu a returnat campul choices[0].message.content.'
  );
}

let rezultat;

try {
  rezultat = JSON.parse(content);
} catch (error) {
  throw new Error(
    `Raspunsul OpenAI nu este JSON valid: ${error.message}`
  );
}

const campuriObligatorii = [
  'client',
  'televizor',
  'fisa_service',
  'control'
];

for (const camp of campuriObligatorii) {
  if (
    !Object.prototype.hasOwnProperty.call(rezultat, camp) ||
    typeof rezultat[camp] !== 'object' ||
    rezultat[camp] === null
  ) {
    throw new Error(
      `Lipseste obiectul obligatoriu: ${camp}`
    );
  }
}

const statusuriPermise = [
  'nespecificat',
  'in_asteptare',
  'confirmata',
  'anulata'
];

if (!statusuriPermise.includes(rezultat.fisa_service.status)) {
  throw new Error(
    `Status AI nepermis: ${rezultat.fisa_service.status}`
  );
}

const valoareSauNull = (valoare) => {
  if (valoare === undefined || valoare === null) {
    return null;
  }

  if (typeof valoare === 'string') {
    const curatat = valoare.trim();
    const curatatLower = curatat.toLowerCase();

    if (
      curatat === '' ||
      curatatLower === 'null' ||
      curatatLower === 'empty' ||
      curatatLower === 'necunoscut'
    ) {
      return null;
    }

    return curatat;
  }

  return valoare;
};

const normalizareObiect = (obiect) => {
  return Object.fromEntries(
    Object.entries(obiect).map(([cheie, valoare]) => [
      cheie,
      valoareSauNull(valoare)
    ])
  );
};

const dataCalendaristicaValida = (valoare) => {
  if (typeof valoare !== 'string') {
    return false;
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(valoare)) {
    return false;
  }

  const data = new Date(`${valoare}T00:00:00Z`);

  return (
    !Number.isNaN(data.getTime()) &&
    data.toISOString().slice(0, 10) === valoare
  );
};

const oraValida = (valoare) => {
  if (typeof valoare !== 'string') {
    return false;
  }

  return /^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(
    valoare
  );
};

const client = normalizareObiect(rezultat.client);
const televizor = normalizareObiect(rezultat.televizor);
const fisaService = normalizareObiect(
  rezultat.fisa_service
);

const control = {
  ...rezultat.control,
  motiv_verificare: valoareSauNull(
    rezultat.control.motiv_verificare
  )
};

if (
  fisaService.data_programare !== null &&
  !dataCalendaristicaValida(
    fisaService.data_programare
  )
) {
  fisaService.data_programare = null;
}

if (
  fisaService.ora_programare !== null &&
  !oraValida(fisaService.ora_programare)
) {
  fisaService.ora_programare = null;
}

const programareIncompleta =
  fisaService.data_programare === null ||
  fisaService.ora_programare === null;

if (
  fisaService.status === 'confirmata' &&
  programareIncompleta
) {
  fisaService.status = 'in_asteptare';
  control.necesita_raspuns = true;
}

const context = $('Prepare AI Context').first().json;

if (!context?.client_id) {
  throw new Error(
    'Lipseste client_id din Prepare AI Context.'
  );
}

if (!context?.mesaj_nou?.id) {
  throw new Error(
    'Lipseste ID-ul conversatiei noi.'
  );
}

return {
  json: {
    client_id: context.client_id,
    conversation_id: context.mesaj_nou.id,
    message_id:
      context.mesaj_nou.message_id ?? null,

    client,
    televizor,
    fisa_service: fisaService,
    control,

    meta: {
      model: response.model ?? null,
      prompt_tokens:
        response.usage?.prompt_tokens ?? null,
      completion_tokens:
        response.usage?.completion_tokens ?? null,
      total_tokens:
        response.usage?.total_tokens ?? null,
      analizat_la: new Date().toISOString()
    }
  }
};
